// Extract incoming message details from Meta payload
const body = $input.item.json.body || {};
const entries = body.entry || [];
let results = [];

for (const entry of entries) {
  const messaging = entry.messaging || [];
  for (const event of messaging) {
    if (event.message && !event.message.is_echo) {
      const senderId = event.sender?.id;
      const text = event.message.text || '';

      if (senderId && text) {
        // Rule-based / Smart Lead Logic
        const clean = text.toLowerCase().trim();
        // Word-boundary match: substring checks misfire on 'this', 'which', '31', '12'
        const has = (words) => new RegExp(`\\b(?:${words})\\b`).test(clean);
        const isEmail = /[^\s@]+@[^\s@]+\.[^\s@]+/.test(text);
        let reply = '';
        let leadType = 'General Inquiry';

        if (isEmail) {
          reply = 'Thank you! We received your email. Our team will review your info and get in touch shortly!';
          leadType = 'Captured Email';
        } else if (has('hi|hello|hey|start|info')) {
          reply = 'Hi there! Welcome to Bloom Craft! \u{1F44B}\n\nWe help businesses scale with custom automation & growth tools.\n\nHow can we help today?\n1. \u{1F4BC} View our services\n2. \u{1F4C5} Book a 15-min discovery call\n3. \u{1F4AC} Talk to our team';
        } else if (has('call|book|meeting|2')) {
          reply = 'Awesome! Pick a convenient 15-min slot on our calendar:\n\u{1F449} https://calendly.com\n\nWhat is your best email address to send meeting notes to?';
          leadType = 'Booking Request';
        } else if (has('service|price|pricing|cost|1')) {
          reply = 'We create tailored solutions based on your company stage! \u{1F680}\n\nWhat industry is your company in, and what would you like to automate?';
          leadType = 'Pricing Inquiry';
        } else if (has('human|team|person|representative|rep|3')) {
          reply = 'You got it! I have notified our team. A specialist will reply right here shortly.';
          leadType = 'Human Handoff';
        } else {
          reply = `Thanks for reaching out! We received your message: "${text}".\n\nReply 1 to explore services, or 2 to book a call!`;
        }

        results.push({
          sender_id: senderId,
          message_id: event.message.mid || '',
          incoming_message: text,
          lead_type: leadType,
          reply_message: reply,
          access_token: $env.META_PAGE_ACCESS_TOKEN
        });
      }
    }
  }
}

return results;

